class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        result: List[List[int]] = []
        path: List[int] = []
        used = [False] * len(nums)

        def dfs() -> None:
            if len(path) == len(nums):
                result.append(path[:])
                return
            for i, v in enumerate(nums):
                if used[i]:                    # already in the path: skip (prunes the branch)
                    continue
                used[i] = True
                path.append(v)
                dfs()
                path.pop()
                used[i] = False                # restore for sibling branches

        dfs()
        return result

class Solution:
    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort()                                     # line duplicates up side by side
        result: List[List[int]] = []
        path: List[int] = []

        def dfs(start: int) -> None:
            result.append(path[:])
            for i in range(start, len(nums)):
                if i > start and nums[i] == nums[i - 1]:
                    continue                            # same value as a sibling: prune
                path.append(nums[i])
                dfs(i + 1)
                path.pop()

        dfs(0)
        return result

class Solution:
    def combinationSum2(self, candidates: List[int], target: int) -> List[List[int]]:
        candidates.sort()
        result: List[List[int]] = []
        path: List[int] = []

        def dfs(start: int, remaining: int) -> None:
            if remaining == 0:
                result.append(path[:])
                return
            for i in range(start, len(candidates)):
                if candidates[i] > remaining:
                    break                               # sorted: later values are even bigger
                if i > start and candidates[i] == candidates[i - 1]:
                    continue                            # duplicate sibling: same subtree
                path.append(candidates[i])
                dfs(i + 1, remaining - candidates[i])   # i+1: each index used at most once
                path.pop()

        dfs(0, target)
        return result

